import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_monitor_flag_rate_includes_none_in_denominator():
    events = [{"flagged": True}, {"flagged": False}, {"flagged": None}]
    assert monitor_flag_rate(events) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (5, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_transcript_log_skips_lines_and_decodes_flags():
    lines = ["", " \t\n", "  # comment", " a , 1 , 1 ", "b, 2, 0", "c,3,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("invalid_line", ["x,1", "x,1,0,extra", "x,no,1"])
def test_parse_transcript_log_reports_original_line_number(invalid_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,0", invalid_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts():
    events = parse_transcript_log(["b,4,1", "a,2,1", "c,1,0", "b,2,0", "a,2,"])
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range_events():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,3,", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_rounds_pooled_rate_and_uses_calendar_days():
    groups = {"a": parse_transcript_log(["a,1,1", "b,4,1"]), "b": parse_transcript_log(["c,4,"]), "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": False}], "b": [{"flagged": True}], "empty": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "b", "z"]


def test_flag_rate_by_group_sorts_names_and_distinguishes_empty_groups():
    groups = {"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_flag_streak_resets_at_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0

